contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function that performs the property-based test
    function run(address caller) public payable {
        require(true);

        // Ensure the caller in context is the test contract's address when interacting with c.
        // The contract C's functions use msg.sender, which will be this contract.

        // Read balance before
        uint before = c.tokenBalance(address(this));

        // Attempt to call airDrop and detect revert
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balance after
        uint after = c.tokenBalance(address(this));

        // Check that _locked is false after the operation by calling the public getter
        bool lockedAfter = c._locked();

        // General rule:
        // If the call reverted then balance must be unchanged (since state reverts),
        // otherwise balance must have increased by exactly 20.
        // In all cases, the reentrancy lock must be false afterwards.
        assert((reverted && after == before || !reverted && after == before + 20) && lockedAfter == false);
    }

    // receive to accept ether if needed
    receive() external payable {}
}

