contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an address parameter 'caller' which will be used via Bank by c's supportsToken modifier.
    // The only interaction that changes c's state is calling airDrop. We must call it as msg.sender equal to this contract,
    // because supportsToken uses Bank(msg.sender).supportsToken() — so we rely on the fact that Bank at address
    // `caller` must match the keccak256("Nu Token"). To simulate that, we will deploy nothing; instead we pass
    // an address and ensure that address is the known Bank contract by calling its supportsToken via a view check.

    function run(address bankAddr) public payable {
        require(bankAddr != address(0));

        // Read balance before
        uint before = c.tokenBalance(address(this));

        // Check whether the provided bankAddr advertises support for the token string.
        // This is a view call on the external Bank-like address; if it does not match, then c.airDrop should revert
        // because supportsToken modifier will fail. We capture whether the supportsToken bytes32 matches expected.
        bytes32 declared = BankLike(bankAddr).supportsToken();
        bool bankMatches = (declared == keccak256(abi.encodePacked("Nu Token")));

        // Perform the state-changing call; catch revert.
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = c.tokenBalance(address(this));

        // General rule: If call reverted, balance must be unchanged. If it did not revert, then the precondition hasNoBalance
        // required tokenBalance was 0 and the effect is an increase by exactly 20.
        assert(
            (reverted && after == before)
            || (!reverted && before == 0 && after == before + 20 && bankMatches)
        );
    }

    receive() external payable {}
}

// Minimal interface to call supportsToken on arbitrary address
interface BankLike {
    function supportsToken() external view returns (bytes32);
}

