contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function takes an address to act as the Bank (msg.sender for supportsToken check)
    // We will call c.airDrop() from this contract; supportsToken modifier calls Bank(msg.sender).supportsToken()
    // so msg.sender inside that modifier is this contract's address. We provide a Bank-like address via param bankAddr.

    function run(address bankAddr) public payable {
        require(bankAddr != address(0));

        // read balance before
        uint before = c.tokenBalance(address(this));

        // attempt the call and record whether it reverted
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balance after
        uint after = c.tokenBalance(address(this));

        // If the call reverted, balance must be unchanged. If it didn't revert, balance must have increased by exactly 20.
        assert(reverted ? (after == before) : (after == before + 20));
    }

    // Provide supportsToken for the modifier: when c checks Bank(msg.sender).supportsToken(), it will call this contract.
    // This fallback is used to return the keccak256("Nu Token") bytes32 value as if a Bank supported the token.
    receive() external payable {}

    fallback() external payable {
        // The modifier expects a bytes32 return value from supportsToken(). We return it via low-level return.
        // Solidity does not allow returning bytes from fallback directly; instead we encode and return using assembly.
        bytes32 v = keccak256(abi.encodePacked("Nu Token"));
        assembly {
            mstore(0x0, v)
            return(0x0, 32)
        }
    }
}

